"""Market facts from data/markets.json, and the notice shown before a run.

The facts are quoted, not paraphrased, and always shown with the date they
were checked, because they go stale.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Dict, List, Optional

BAR_LABELS = {
    "ai_writing": "text written or generated by AI",
    "ai_editing": "AI editing of any part of the text",
    "ai_assistance": "AI assistance",
    "ai_any_point": "AI use at any point",
}
# Bars that cover what this app does even in diagnosis-only mode.
BARS_COVERING_DIAGNOSIS = {"ai_assistance", "ai_any_point"}


def load(path: Path) -> List[Dict]:
    if not path.is_file():
        return []
    return json.loads(path.read_text(encoding="utf-8")).get("markets", [])


def find(markets: List[Dict], market_id: Optional[str]) -> Optional[Dict]:
    if not market_id:
        return None
    return next((m for m in markets if m["id"] == market_id), None)


def rewrite_blocked(market: Optional[Dict]) -> bool:
    """Rewrite mode is off for any market that bars AI-written or AI-edited text.

    Taking a suggested rewrite would put AI-written text into the story, so
    a bar on AI writing rules it out as surely as a bar on AI editing.
    """
    if not market:
        return False
    return bool(market.get("ai_policy", {}).get("bars"))


def notice(market: Optional[Dict], word_count: Optional[int] = None) -> Optional[Dict]:
    """What the page shows before a run when a market is chosen."""
    if not market:
        return None
    policy = market.get("ai_policy", {})
    bars = policy.get("bars", [])
    statements: List[str] = []
    if bars:
        statements.append(
            "This market's guidelines rule out " + ", ".join(BAR_LABELS.get(b, b) for b in bars) + "."
        )
        statements.append("Rewrite mode is off for this market.")
    if set(bars) & BARS_COVERING_DIAGNOSIS:
        statements.append(
            "An editorial read by this app is AI assistance. Read the market's wording above and decide "
            "whether to use the app at all on a story you will send there."
        )
    elif bars:
        statements.append(
            "The app's default mode only diagnoses: it does not write or edit your text. Read the market's "
            "wording above and decide whether that is acceptable for this submission."
        )

    length = market.get("length", {})
    if word_count is not None:
        lo, hi = length.get("min_words"), length.get("max_words")
        if lo and word_count < lo:
            statements.append(f"At {word_count:,} words the story is under this market's minimum of {lo:,}.")
        if hi and word_count > hi:
            statements.append(f"At {word_count:,} words the story is over this market's limit of {hi:,}.")

    return {
        "id": market["id"],
        "name": market["name"],
        "url": market["url"],
        "date_checked": market["date_checked"],
        "length_wording": length.get("wording", ""),
        "ai_heading": policy.get("heading", ""),
        "ai_wording": policy.get("wording", ""),
        "rewrite_blocked": rewrite_blocked(market),
        "statements": statements,
    }
